/* ================== TECHNOLOGY 3D DISPLAY ================== */

function cloneAndNormalizeModel(source, targetWidth, widthMode = "max") {
    const object = source.clone(true);

    object.position.set(0, 0, 0);
    object.rotation.set(0, 0, 0);
    object.scale.set(1, 1, 1);

    object.traverse((child) => {
        if (!child.isMesh) return;

        child.castShadow = true;
        child.receiveShadow = true;

        if (Array.isArray(child.material)) {
            child.material = child.material.map((material) => material.clone());
        } else if (child.material) {
            child.material = child.material.clone();
        }
    });

    object.updateMatrixWorld(true);

    const box = new THREE.Box3().setFromObject(object);
    const size = box.getSize(new THREE.Vector3());
    const center = box.getCenter(new THREE.Vector3());

    const measuredWidth =
        widthMode === "x"
            ? Math.max(size.x, 0.001)
            : Math.max(size.x, size.z, 0.001);

    const normalizedScale = targetWidth / measuredWidth;

    object.scale.setScalar(normalizedScale);

    object.position.set(
        -center.x * normalizedScale,
        -box.min.y * normalizedScale,
        -center.z * normalizedScale
    );

    object.updateMatrixWorld(true);

    return {
        object,
        width: size.x * normalizedScale,
        height: size.y * normalizedScale,
        depth: size.z * normalizedScale,
    };
}

function shiftHex(hex, amount = 0) {
    const value = hex.replace("#", "");

    const num = parseInt(value, 16);

    let r = (num >> 16) + amount;
    let g = ((num >> 8) & 0x00ff) + amount;
    let b = (num & 0x0000ff) + amount;

    r = Math.max(0, Math.min(255, r));
    g = Math.max(0, Math.min(255, g));
    b = Math.max(0, Math.min(255, b));

    return `#${(
        (1 << 24) +
        (r << 16) +
        (g << 8) +
        b
    )
        .toString(16)
        .slice(1)}`;
}

function createPhysicalMaterial(sourceMaterial, settings = {}) {
    const material = new THREE.MeshPhysicalMaterial({
        name: sourceMaterial?.name || "",

        color:
            sourceMaterial?.color?.clone() ||
            new THREE.Color("#ffffff"),

        map: sourceMaterial?.map || null,
        normalMap: sourceMaterial?.normalMap || null,
        roughnessMap: sourceMaterial?.roughnessMap || null,
        metalnessMap: sourceMaterial?.metalnessMap || null,
        aoMap: sourceMaterial?.aoMap || null,
        alphaMap: sourceMaterial?.alphaMap || null,

        side: sourceMaterial?.side ?? THREE.FrontSide,

        ...settings,
    });

    material.needsUpdate = true;

    return material;
}
function TechnologyDisplayModel({
    deviceMode,
    variantLook,
    lightingTheme,
    floorY,
}) {
    const rigRef = useRef(null);

    const { scene: standSource } = useGLTF(asset("/stand.glb"));
    const { scene: glassesSource } = useGLTF(asset("/glasses.glb"));

    /*
     * تم تصغير الستاند وتكبير النظارة:
     * - الستاند أصغر تقريبًا 10–15%
     * - النظارة أكبر تقريبًا 12–18%
     */
    const standModel = useMemo(() => {
        return cloneAndNormalizeModel(
            standSource,
            deviceMode === "mobile" ? 3.85 : 4.45,
            "max"
        );
    }, [standSource, deviceMode]);

    const glassesModel = useMemo(() => {
        return cloneAndNormalizeModel(
            glassesSource,
            deviceMode === "mobile" ? 2.35 : 2.75,
            "x"
        );
    }, [glassesSource, deviceMode]);

    /* ================= نظارة ================= */
    useEffect(() => {
        glassesModel.object.traverse((child) => {
            if (!child.isMesh || !child.material) return;

            child.castShadow = true;
            child.receiveShadow = true;

            const materials = Array.isArray(child.material)
                ? child.material
                : [child.material];

            materials.forEach((material) => {
                const materialName = `
                ${material.name || ""}
                ${child.name || ""}
            `.toLowerCase();

                const isLens =
                    materialName.includes("lens") ||
                    materialName.includes("lenses") ||
                    materialName.includes("glass");

                if (isLens) {
                    /*
                     * عدسات داكنة ومتوازنة.
                     * بدون Transmission لأنه سبب الاحتراق في العدسة اليمنى.
                     */
                    material.color.set("#242a30");

                    material.transparent = true;
                    material.opacity = 0.82;

                    material.roughness = 0.28;
                    material.metalness = 0;

                    material.envMapIntensity = 0.18;

                    if ("transmission" in material) {
                        material.transmission = 0;
                    }

                    if ("ior" in material) {
                        material.ior = 1.45;
                    }

                    if ("clearcoat" in material) {
                        material.clearcoat = 0.08;
                        material.clearcoatRoughness = 0.32;
                    }

                    if ("emissive" in material) {
                        material.emissive.set("#000000");
                        material.emissiveIntensity = 0;
                    }

                    material.depthWrite = true;
                    material.side = THREE.DoubleSide;
                } else {
                    /*
                     * إطار رمادي غامق قريب من #1b1b1b.
                     */
                    material.color.set("#1b1b1b");

                    material.roughness = 0.38;
                    material.metalness = 0.04;
                    material.envMapIntensity = 0.32;

                    if ("clearcoat" in material) {
                        material.clearcoat = 0.12;
                        material.clearcoatRoughness = 0.28;
                    }
                }

                material.needsUpdate = true;
            });
        });
    }, [
            glassesModel.object,
            variantLook.frame,
            variantLook.lens,
        ]);

    /* ================= ستاند ================= */

    useEffect(() => {
        standModel.object.traverse((child) => {
            if (!child.isMesh || !child.material) return;

            child.castShadow = true;
            child.receiveShadow = true;

            const materials = Array.isArray(child.material)
                ? child.material
                : [child.material];

            materials.forEach((material) => {
                const materialName = `
                ${material.name || ""}
                ${child.name || ""}
            `.toLowerCase();

                const originalColor = material.color;

                const looksGold =
                    originalColor &&
                    originalColor.r > originalColor.b * 1.25 &&
                    originalColor.g > originalColor.b * 1.08 &&
                    originalColor.r > 0.15;

                const isAccent =
                    materialName.includes("gold") ||
                    materialName.includes("ring") ||
                    materialName.includes("trim") ||
                    materialName.includes("accent") ||
                    looksGold;

                const isTop =
                    materialName.includes("top") ||
                    materialName.includes("upper") ||
                    materialName.includes("surface");

                if (isAccent) {
                    /*
                     * ذهبي مطفي، وليس أصفر فاقعًا.
                     */
                    material.color.set("#a88d4b");
                    material.roughness = 0.48;
                    material.metalness = 0.52;
                    material.envMapIntensity = 0.35;

                    if ("clearcoat" in material) {
                        material.clearcoat = 0.08;
                        material.clearcoatRoughness = 0.42;
                    }
                } else {
                    /*
                     * جسم الستاند رمادي/أسود.
                     */
                    material.color.set(
                        isTop ? "#1b1b1b" : "#121212"
                    );

                    material.roughness = isTop ? 0.4 : 0.46;
                    material.metalness = 0.05;
                    material.envMapIntensity = 0.26;

                    if ("clearcoat" in material) {
                        material.clearcoat = 0.06;
                        material.clearcoatRoughness = 0.38;
                    }
                }

                material.needsUpdate = true;
            });
        });
    }, [standModel.object]);

    /* ================= حركة العرض ================= */

    useFrame((state, delta) => {
        if (!rigRef.current) return;

        const time = state.clock.getElapsedTime();

        /*
         * دوران محدود:
         * لا يُظهر خلفية النظارة ولا يحولها إلى وضع جانبي كامل.
         */
        const targetRotation =
            0.06 + Math.sin(time * 0.33) * 0.12;

        rigRef.current.rotation.y = THREE.MathUtils.damp(
            rigRef.current.rotation.y,
            targetRotation,
            3,
            delta
        );

        /*
         * حركة عمودية شبه غير ملحوظة.
         */
        const targetY =
            floorY +
            0.1 +
            Math.sin(time * 0.7) * 0.006;

        rigRef.current.position.y = THREE.MathUtils.damp(
            rigRef.current.position.y,
            targetY,
            4,
            delta
        );
    });

    return (
        <group
            ref={rigRef}
            position={[0, floorY + 0.12, 0]}
            scale={deviceMode === "mobile" ? 1 : 1.1}
        >
            <primitive object={standModel.object} />

            <group
                position={[
                    0,
                    standModel.height + 0.025,
                    0.02,
                ]}
                rotation={[0, 0, 0]}
            >
                <primitive object={glassesModel.object} />
            </group>
        </group>
    );
}

function TechnologyDisplayScene({
    deviceMode,
    variantLook,
    lightingTheme,
}) {
    const isMobile = deviceMode === "mobile";

    const floorY = isMobile ? -0.72 : -0.63;

    return (
        <Canvas
            camera={{
                position: isMobile
                    ? [0, 1.15, 7.15]
                    : [0, 1.42, 7.65],

                fov: isMobile ? 35 : 29,

                near: 0.1,
                far: 100,
            }}
            onCreated={({ camera, gl, scene }) => {
                camera.lookAt(0, 0.12, 0);

                gl.outputColorSpace = THREE.SRGBColorSpace;
                gl.toneMapping = THREE.ACESFilmicToneMapping;

                /*
                 * خفض التعريض لمنع احتراق العدسة والستاند.
                 */
                gl.toneMappingExposure = 0.78;

                gl.shadowMap.enabled = true;
                gl.shadowMap.type = THREE.PCFSoftShadowMap;

                gl.setClearColor(0x000000, 0);

                /*
                 * تقليل قوة انعكاس HDRI.
                 */
                if ("environmentIntensity" in scene) {
                    scene.environmentIntensity = 0.32;
                }
            }}
            shadows
            dpr={isMobile ? [1, 1.5] : [1, 2]}
            gl={{
                alpha: true,
                antialias: true,
                powerPreference: "high-performance",
            }}
            style={{
                background: "transparent",
            }}
        >
           {/* إضاءة عامة */}
<ambientLight
    intensity={0.3}
    color="#d8dde3"
/>

{/* إضاءة رئيسية ناعمة من اليسار */}
<directionalLight
    position={[-4, 5, 5]}
    intensity={0.88}
    color="#f2f3f5"
    castShadow
    shadow-bias={-0.0002}
/>

{/* إضاءة تعبئة من اليمين لتوازن العدستين */}
<directionalLight
    position={[4, 3, 4]}
    intensity={0.52}
    color="#d7dde5"
/>

{/* إضاءة حواف خلفية */}
<directionalLight
    position={[0, 3, -5]}
    intensity={0.42}
    color="#aeb8c5"
/>

{/* لمعة أمامية خفيفة جدًا */}
<pointLight
    position={[0, 2.5, 5]}
    intensity={0.14}
    color="#ffffff"
    distance={10}
    decay={2}
/>

            <Suspense fallback={null}>
                <TechnologyDisplayModel
                    deviceMode={deviceMode}
                    variantLook={variantLook}
                    lightingTheme={lightingTheme}
                    floorY={floorY}
                />

                <ContactShadows
                    position={[0, floorY + 0.1, 0]}
                    opacity={0.42}
                    scale={5.5}
                    blur={3.2}
                    far={3.8}
                    resolution={isMobile ? 256 : 512}
                    color="#000000"
                />

                <Environment
                    preset="studio"
                    background={false}
                />
            </Suspense>
        </Canvas>
    );
}

