// src/Product.js

import React, { useEffect, useMemo, useState } from "react";
import {
    Link,
    useNavigate,
    useParams,
    useSearchParams,
} from "react-router-dom";
import { motion, AnimatePresence } from "framer-motion";
import "./App.css";
import { useCart } from "./CartContext";
import { PRODUCTS, asset } from "./productsData";

export default function Product() {
    const { addItem, count } = useCart();
    const navigate = useNavigate();
    const { productId } = useParams();
    const [searchParams, setSearchParams] = useSearchParams();

    const product = useMemo(() => {
        return PRODUCTS.find((item) => item.id === productId) || PRODUCTS[0];
    }, [productId]);

    const gallery = product.gallery || [];
    const requestedView = searchParams.get("view");

    const requestedIndex = useMemo(() => {
        const foundIndex = gallery.findIndex(
            (item) => item.id === requestedView
        );

        return foundIndex >= 0 ? foundIndex : 0;
    }, [gallery, requestedView]);

    const [activeImage, setActiveImage] = useState(requestedIndex);
    const [selectedColorId, setSelectedColorId] = useState(
        product.colorOptions?.find((option) => option.available)?.id || ""
    );

    useEffect(() => {
        setActiveImage(requestedIndex);
    }, [requestedIndex, product.id]);

    useEffect(() => {
        const firstAvailable =
            product.colorOptions?.find((option) => option.available)?.id || "";

        setSelectedColorId(firstAvailable);
    }, [product.id, product.colorOptions]);

    const activeGalleryItem = gallery[activeImage] || gallery[0];

    const selectedColor =
        product.colorOptions?.find(
            (option) => option.id === selectedColorId
        ) || product.colorOptions?.[0];

    const savings = Math.max(
        0,
        Number(product.compareAt) - Number(product.price)
    );

    const suggestedProducts = PRODUCTS.filter(
        (item) => item.id !== product.id
    );

    const selectImage = (index) => {
        const nextItem = gallery[index];
        if (!nextItem) return;

        setActiveImage(index);
        setSearchParams(
            {
                view: nextItem.id,
            },
            {
                replace: true,
            }
        );
    };

    const handleAddToCart = () => {
        addItem({
            id: `ideal-${product.id}-${selectedColor?.id || "default"}`,
            productId: product.id,
            sku: product.sku,
            title: product.name,
            variant: selectedColor?.label || product.label,
            price: Number(product.price),
            image: gallery[0]?.src || product.suggestionImage,
        });
    };

    const handleSuggestedView = (targetId) => {
        navigate(`/product/${targetId}?view=front`);
        window.scrollTo({ top: 0, behavior: "smooth" });
    };

    if (!activeGalleryItem) {
        return (
            <div className="page product-page">
                <main className="product-main">
                    <div className="container">
                        <p>No product images were found.</p>
                    </div>
                </main>
            </div>
        );
    }

    return (
        <div
            className={`page product-page ${product.accent}`}
            style={{ background: product.gradient }}
        >
            <header className="nav product-nav">
                <div className="container nav-inner">
                    <Link
                        to="/"
                        className="logo"
                        style={{ textDecoration: "none", color: "inherit" }}
                    >
                        IDEAL.
                    </Link>

                    <nav className="nav-links" aria-label="Product navigation">
                        <Link to="/products">Products</Link>
                        <Link to="/specs">Specs</Link>
                        <a href="#details">Details</a>
                    </nav>

                    <Link to="/checkout" className="nav-cta cart-cta">
                        Pre-order
                        {count > 0 && <span className="cart-badge">{count}</span>}
                    </Link>
                </div>
            </header>

            <div className="tech-grid-overlay product-grid" />

            <main className="product-main">
                <div className="container product-shell">
                    <section
                        className="product-gallery"
                        aria-label="IDEAL product gallery"
                    >
                        <div className="product-media glass-card">
                            <AnimatePresence mode="wait">
                                <motion.img
                                    key={`${product.id}-${activeGalleryItem.id}`}
                                    src={asset(activeGalleryItem.src)}
                                    alt={activeGalleryItem.alt}
                                    className="product-hero-img"
                                    initial={{
                                        opacity: 0,
                                        scale: 0.985,
                                        filter: "blur(10px)",
                                    }}
                                    animate={{
                                        opacity: 1,
                                        scale: 1,
                                        filter: "blur(0px)",
                                    }}
                                    exit={{
                                        opacity: 0,
                                        scale: 1.015,
                                        filter: "blur(10px)",
                                    }}
                                    transition={{
                                        duration: 0.35,
                                        ease: [0.22, 1, 0.36, 1],
                                    }}
                                />
                            </AnimatePresence>

                            <div className="product-glow" />

                            <div className="product-image-label">
                                <span>{activeGalleryItem.title}</span>
                                <small>
                                    {activeImage + 1} / {gallery.length}
                                </small>
                            </div>
                        </div>

                        <div
                            className="product-thumbs product-thumbs-eight"
                            role="list"
                            aria-label="Choose a product view"
                        >
                            {gallery.map((item, index) => (
                                <button
                                    key={item.id}
                                    className={`thumb ${index === activeImage ? "active" : ""
                                        }`}
                                    onClick={() => selectImage(index)}
                                    type="button"
                                    aria-label={`Open ${item.title}`}
                                    aria-pressed={index === activeImage}
                                    role="listitem"
                                >
                                    <img
                                        src={asset(item.src)}
                                        alt=""
                                        loading="lazy"
                                    />
                                    <span>{item.shortTitle}</span>
                                </button>
                            ))}
                        </div>

                        <div className="product-mini-specs">
                            {product.bullets.map((text) => (
                                <div key={text} className="mini-pill">
                                    <span className="mini-dot" />
                                    <span>{text}</span>
                                </div>
                            ))}
                        </div>

                        {suggestedProducts.length > 0 && (
                            <div className="product-suggestions">
                                <p className="suggestions-title">
                                    Recommended styles
                                </p>

                                <div className="suggestions-grid">
                                    {suggestedProducts.map((item) => (
                                        <article
                                            key={item.id}
                                            className="suggestion-card glass-card"
                                        >
                                            <img
                                                src={asset(item.suggestionImage)}
                                                alt={item.label}
                                            />

                                            <div className="suggestion-body">
                                                <h4>{item.label}</h4>
                                                <p>{item.suggestionDesc}</p>

                                                <div className="suggestion-meta">
                                                    <span>${item.price}</span>

                                                    <button
                                                        type="button"
                                                        className="suggestion-view"
                                                        onClick={() =>
                                                            handleSuggestedView(
                                                                item.id
                                                            )
                                                        }
                                                    >
                                                        View
                                                    </button>
                                                </div>
                                            </div>
                                        </article>
                                    ))}
                                </div>
                            </div>
                        )}
                    </section>

                    <section className="product-info">
                        <motion.div
                            className="product-info-card glass-card"
                            initial={{
                                opacity: 0,
                                y: 18,
                                filter: "blur(10px)",
                            }}
                            animate={{
                                opacity: 1,
                                y: 0,
                                filter: "blur(0px)",
                            }}
                            transition={{
                                duration: 0.5,
                                ease: [0.22, 1, 0.36, 1],
                            }}
                        >
                            <p className="eyebrow">PRODUCT · {product.sku}</p>

                            <h1 className="product-title">
                                {product.productTitle.split(" ")[0]}{" "}
                                <span>
                                    {product.productTitle
                                        .split(" ")
                                        .slice(1)
                                        .join(" ")}
                                </span>
                            </h1>

                            <p className="product-tagline">
                                {product.productTagline}
                            </p>

                            <div className="product-rating">
                                <span className="stars">★★★★★</span>
                                <span className="rating-text">
                                    {product.rating} · {product.reviews} reviews
                                </span>
                            </div>

                            <div className="product-price-row">
                                <div className="price">
                                    <span className="now">${product.price}</span>
                                    <span className="was">
                                        ${product.compareAt}
                                    </span>
                                </div>

                                <div className="save">Save ${savings}</div>
                            </div>

                            <div className="product-variants">
                                <p className="variant-label">Color</p>

                                <div className="variant-buttons">
                                    {product.colorOptions.map((option) => (
                                        <button
                                            key={option.id}
                                            type="button"
                                            disabled={!option.available}
                                            onClick={() => {
                                                if (option.available) {
                                                    setSelectedColorId(option.id);
                                                }
                                            }}
                                            className={`variant-btn ${option.id === selectedColorId
                                                    ? "active"
                                                    : ""
                                                }`}
                                        >
                                            <span
                                                className="variant-swatch"
                                                style={{
                                                    background: option.swatch,
                                                }}
                                            />
                                            {option.label}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            <div className="selected-view-copy">
                                <span>{activeGalleryItem.title}</span>
                                <p>{activeGalleryItem.description}</p>
                            </div>

                            <div className="product-actions">
                                <button
                                    type="button"
                                    className="primary-cta product-buy"
                                    onClick={handleAddToCart}
                                >
                                    Pre-order now
                                </button>

                                <Link
                                    to="/specs"
                                    className="secondary-cta product-specs"
                                >
                                    View specs
                                </Link>
                            </div>

                            <div className="product-shipping">
                                <div className="ship-item">
                                    <span className="ship-icon">✓</span>
                                    30-day comfort guarantee
                                </div>
                                <div className="ship-item">
                                    <span className="ship-icon">✓</span>
                                    Worldwide shipping
                                </div>
                                <div className="ship-item">
                                    <span className="ship-icon">✓</span>
                                    Secure checkout
                                </div>
                            </div>
                        </motion.div>

                        <div className="product-details" id="details">
                            <div className="detail-card glass-card">
                                <h3>{product.detailTitle}</h3>
                                <p>{product.detailDesc}</p>
                            </div>

                            <div className="detail-card glass-card">
                                <h3>What you get</h3>
                                <p>{product.packageIncludes.join(" · ")}</p>
                            </div>
                        </div>
                    </section>
                </div>
            </main>
        </div>
    );
}
