// src/productsData.js

export const asset = (src = "") => {
    if (!src) return "";

    if (
        src.startsWith("http") ||
        src.startsWith("data:") ||
        (
            process.env.PUBLIC_URL &&
            src.startsWith(process.env.PUBLIC_URL)
        )
    ) {
        return src;
    }

    const normalizedSrc = src.startsWith("/")
        ? src
        : `/${src}`;

    return `${process.env.PUBLIC_URL || ""}${normalizedSrc}`;
};


