// src/App.js

import React from "react";

import {
    HashRouter,
    Routes,
    Route,
} from "react-router-dom";

import Landing from "./Landing";
import Products from "./Products";
import Product from "./Product";
import Specs from "./Specs";
import Checkout from "./Checkout";

import {
    CartProvider,
} from "./CartContext";

export default function App() {
    return (
        <CartProvider>
            <HashRouter>
                <Routes>
                    <Route
                        path="/"
                        element={<Landing />}
                    />

                    <Route
                        path="/products"
                        element={<Products />}
                    />

                    <Route
                        path="/product/:productId"
                        element={<Product />}
                    />

                    <Route
                        path="/specs"
                        element={<Specs />}
                    />

                    <Route
                        path="/checkout"
                        element={<Checkout />}
                    />
                </Routes>
            </HashRouter>
        </CartProvider>
    );
}