// src/Product.js

import React, {
    useEffect,
    useMemo,
    useState,
} from "react";

import {
    Link,
    useNavigate,
    useParams,
    useSearchParams,
} from "react-router-dom";

import {
    motion,
    AnimatePresence,
} from "framer-motion";

import "./App.css";

import { useCart } from "./CartContext";

import {
    PRODUCTS,
    asset,
} from "./productsData";

export default function Product() {
    const {
        addItem,
        count,
    } = useCart();

    const navigate = useNavigate();

    const { productId } = useParams();

    const [
        searchParams,
        setSearchParams,
    ] = useSearchParams();

    /*
     * البحث عن المنتج اعتمادًا على id الموجود في الرابط.
     *
     * مثال:
     * /product/classic
     */
    const product = useMemo(() => {
        return (
            PRODUCTS.find(
                (item) => item.id === productId
            ) || PRODUCTS[0]
        );
    }, [productId]);

    /*
     * الصور الثماني الموجودة داخل productsData.js
     */
    const gallery = product.gallery || [];

    /*
     * قراءة اسم الصورة من الرابط.
     *
     * مثال:
     * /product/classic?view=hinge
     */
    const requestedView =
        searchParams.get("view");

    /*
     * معرفة رقم الصورة المطلوبة داخل gallery.
     */
    const requestedIndex = useMemo(() => {
        const foundIndex = gallery.findIndex(
            (item) => item.id === requestedView
        );

        return foundIndex >= 0
            ? foundIndex
            : 0;
    }, [
        gallery,
        requestedView,
    ]);

    /*
     * الصورة المفتوحة حاليًا.
     */
    const [
        activeImage,
        setActiveImage,
    ] = useState(requestedIndex);

   

    /*
     * تغيير الصورة عند تغير ?view= في الرابط.
     */
    useEffect(() => {
        setActiveImage(requestedIndex);
    }, [
        requestedIndex,
        product.id,
    ]);

    /*
     * إعادة اختيار أول لون متوفر عند تغير المنتج.
     */
    

    /*
     * بيانات الصورة المعروضة حاليًا.
     */
    const activeGalleryItem =
        gallery[activeImage] ||
        gallery[0];

    /*
     * بيانات اللون المختار.
     */
   

    /*
     * قيمة الخصم.
     */
    const savings = Math.max(
        0,
        Number(product.compareAt) -
        Number(product.price)
    );

    /*
     * منتجات أخرى غير المنتج الحالي.
     *
     * حاليًا لديك منتج واحد فقط،
     * لذلك لن يظهر قسم Recommended styles.
     */
    const suggestedProducts =
        PRODUCTS.filter(
            (item) => item.id !== product.id
        );

    /*
     * فتح صورة من الصور المصغرة
     * وتحديث الرابط.
     */
    const selectImage = (index) => {
        const nextItem = gallery[index];

        if (!nextItem) {
            return;
        }

        setActiveImage(index);

        setSearchParams(
            {
                view: nextItem.id,
            },
            {
                replace: true,
            }
        );
    };

    /*
     * إضافة المنتج إلى السلة.
     */
    const handleAddToCart = () => {
        addItem({
            id: `ideal-${product.id}`,

            productId: product.id,

            sku: product.sku,

            title: product.name,

            variant: product.label,

            price: Number(product.price),

            image: asset(
                gallery[0]?.src ||
                product.suggestionImage
            ),
        });
    };
    /*
     * فتح منتج مقترح.
     */
    const handleSuggestedView = (
        targetId
    ) => {
        navigate(
            `/product/${targetId}?view=front`
        );

        window.scrollTo({
            top: 0,
            behavior: "smooth",
        });
    };

    /*
     * حماية في حال لم توجد صور.
     */
    if (!activeGalleryItem) {
        return (
            <div className="page product-page">
                <main className="product-main">
                    <div className="container">
                        <p>
                            No product images were found.
                        </p>
                    </div>
                </main>
            </div>
        );
    }

    return (
        <div
            className={`page product-page ${product.accent}`}
            style={{
                background: product.gradient,
            }}
        >
            {/* ================= NAVBAR ================= */}

            <header className="nav product-nav">
                <div className="container nav-inner">
                    <Link
                        to="/"
                        className="logo"
                        style={{
                            textDecoration: "none",
                            color: "inherit",
                        }}
                    >
                        IDEAL.
                    </Link>

                    <nav
                        className="nav-links"
                        aria-label="Product navigation"
                    >
                        <Link to="/products">
                            Products
                        </Link>

                        <Link to="/specs">
                            Specs
                        </Link>

                        <a href="#details">
                            Details
                        </a>
                    </nav>

                    <Link
                        to="/checkout"
                        className="nav-cta cart-cta"
                    >
                        Pre-order

                        {count > 0 && (
                            <span className="cart-badge">
                                {count}
                            </span>
                        )}
                    </Link>
                </div>
            </header>

            <div className="tech-grid-overlay product-grid" />

            {/* ================= PRODUCT ================= */}

            <main className="product-main">
                <div className="container product-shell">

                    {/* ================= GALLERY ================= */}

                    <section
                        className="product-gallery"
                        aria-label="IDEAL product gallery"
                    >
                        {/* الصورة الرئيسية */}

                        <div className="product-media glass-card">
                            <AnimatePresence mode="wait">
                                <motion.img
                                    key={`${product.id}-${activeGalleryItem.id}`}
                                    src={asset(
                                        activeGalleryItem.src
                                    )}
                                    alt={
                                        activeGalleryItem.alt
                                    }
                                    className="product-hero-img"
                                    initial={{
                                        opacity: 0,
                                        scale: 0.985,
                                        filter:
                                            "blur(10px)",
                                    }}
                                    animate={{
                                        opacity: 1,
                                        scale: 1,
                                        filter:
                                            "blur(0px)",
                                    }}
                                    exit={{
                                        opacity: 0,
                                        scale: 1.015,
                                        filter:
                                            "blur(10px)",
                                    }}
                                    transition={{
                                        duration: 0.35,
                                        ease: [
                                            0.22,
                                            1,
                                            0.36,
                                            1,
                                        ],
                                    }}
                                />
                            </AnimatePresence>

                            <div className="product-glow" />

                            {/* اسم الصورة وعددها */}

                            <div className="product-image-label">
                                <span>
                                    {
                                        activeGalleryItem.title
                                    }
                                </span>

                                <small>
                                    {activeImage + 1}
                                    {" / "}
                                    {gallery.length}
                                </small>
                            </div>
                        </div>

                        {/* الصور الثماني المصغرة */}

                        <div
                            className="product-thumbs product-thumbs-eight"
                            role="list"
                            aria-label="Choose a product view"
                        >
                            {gallery.map(
                                (item, index) => (
                                    <button
                                        key={item.id}
                                        className={`thumb ${index ===
                                                activeImage
                                                ? "active"
                                                : ""
                                            }`}
                                        onClick={() =>
                                            selectImage(
                                                index
                                            )
                                        }
                                        type="button"
                                        aria-label={`Open ${item.title}`}
                                        aria-pressed={
                                            index ===
                                            activeImage
                                        }
                                        role="listitem"
                                    >
                                        <img
                                            src={asset(
                                                item.src
                                            )}
                                            alt=""
                                            loading="lazy"
                                        />

                                        <span>
                                            {
                                                item.shortTitle
                                            }
                                        </span>
                                    </button>
                                )
                            )}
                        </div>

                        {/* المواصفات المختصرة */}

                        <div className="product-mini-specs">
                            {product.bullets.map(
                                (text) => (
                                    <div
                                        key={text}
                                        className="mini-pill"
                                    >
                                        <span className="mini-dot" />

                                        <span>
                                            {text}
                                        </span>
                                    </div>
                                )
                            )}
                        </div>

                        {/* المنتجات المقترحة */}

                        {suggestedProducts.length >
                            0 && (
                                <div className="product-suggestions">
                                    <p className="suggestions-title">
                                        Recommended styles
                                    </p>

                                    <div className="suggestions-grid">
                                        {suggestedProducts.map(
                                            (item) => (
                                                <article
                                                    key={
                                                        item.id
                                                    }
                                                    className="suggestion-card glass-card"
                                                >
                                                    <img
                                                        src={asset(
                                                            item.suggestionImage
                                                        )}
                                                        alt={
                                                            item.label
                                                        }
                                                    />

                                                    <div className="suggestion-body">
                                                        <h4>
                                                            {
                                                                item.label
                                                            }
                                                        </h4>

                                                        <p>
                                                            {
                                                                item.suggestionDesc
                                                            }
                                                        </p>

                                                        <div className="suggestion-meta">
                                                            <span>
                                                                $
                                                                {
                                                                    item.price
                                                                }
                                                            </span>

                                                            <button
                                                                type="button"
                                                                className="suggestion-view"
                                                                onClick={() =>
                                                                    handleSuggestedView(
                                                                        item.id
                                                                    )
                                                                }
                                                            >
                                                                View
                                                            </button>
                                                        </div>
                                                    </div>
                                                </article>
                                            )
                                        )}
                                    </div>
                                </div>
                            )}
                    </section>

                    {/* ================= PRODUCT INFO ================= */}

                    <section className="product-info">
                        <motion.div
                            className="product-info-card glass-card"
                            initial={{
                                opacity: 0,
                                y: 18,
                                filter: "blur(10px)",
                            }}
                            animate={{
                                opacity: 1,
                                y: 0,
                                filter: "blur(0px)",
                            }}
                            transition={{
                                duration: 0.5,
                                ease: [
                                    0.22,
                                    1,
                                    0.36,
                                    1,
                                ],
                            }}
                        >
                            <p className="eyebrow">
                                PRODUCT · {product.sku}
                            </p>

                            <h1 className="product-title">
                                {
                                    product.productTitle.split(
                                        " "
                                    )[0]
                                }{" "}
                                <span>
                                    {product.productTitle
                                        .split(" ")
                                        .slice(1)
                                        .join(" ")}
                                </span>
                            </h1>

                            <p className="product-tagline">
                                {
                                    product.productTagline
                                }
                            </p>

                            {/* التقييم */}

                            <div className="product-rating">
                                <span className="stars">
                                    ★★★★★
                                </span>

                                <span className="rating-text">
                                    {product.rating}
                                    {" · "}
                                    {product.reviews}
                                    {" reviews"}
                                </span>
                            </div>

                            {/* السعر */}

                            <div className="product-price-row">
                                <div className="price">
                                    <span className="now">
                                        ${product.price}
                                    </span>

                                    <span className="was">
                                        $
                                        {
                                            product.compareAt
                                        }
                                    </span>
                                </div>

                                <div className="save">
                                    Save ${savings}
                                </div>
                            </div>

                            {/* الألوان */}

                            <div className="product-variants">
                                <p className="variant-label">
                                    Style
                                </p>

                                <div className="variant-buttons">
                                    {PRODUCTS.map((variant) => (
                                        <button
                                            key={variant.id}
                                            type="button"

                                            onClick={() => {
                                                navigate(
                                                    `/product/${variant.id}?view=front`
                                                );

                                                setActiveImage(0);

                                                window.scrollTo({
                                                    top: 0,
                                                    behavior: "smooth",
                                                });
                                            }}

                                            className={`variant-btn ${variant.id === product.id
                                                    ? "active"
                                                    : ""
                                                }`}
                                        >
                                            <span
                                                className="variant-swatch"
                                                style={{
                                                    background:
                                                        variant.swatch,
                                                }}
                                            />

                                            {variant.label}
                                        </button>
                                    ))}
                                </div>
                            </div>

                            {/* وصف الصورة المختارة */}

                            <div className="selected-view-copy">
                                <span>
                                    {
                                        activeGalleryItem.title
                                    }
                                </span>

                                <p>
                                    {
                                        activeGalleryItem.description
                                    }
                                </p>
                            </div>

                            {/* أزرار الشراء */}

                            <div className="product-actions">
                                <button
                                    type="button"
                                    className="primary-cta product-buy"
                                    onClick={
                                        handleAddToCart
                                    }
                                >
                                    Pre-order now
                                </button>

                                <Link
                                    to="/specs"
                                    className="secondary-cta product-specs"
                                >
                                    View specs
                                </Link>
                            </div>

                            {/* الشحن والثقة */}

                            <div className="product-shipping">
                                <div className="ship-item">
                                    <span className="ship-icon">
                                        ✓
                                    </span>

                                    30-day comfort guarantee
                                </div>

                                <div className="ship-item">
                                    <span className="ship-icon">
                                        ✓
                                    </span>

                                    Worldwide shipping
                                </div>

                                <div className="ship-item">
                                    <span className="ship-icon">
                                        ✓
                                    </span>

                                    Secure checkout
                                </div>
                            </div>
                        </motion.div>

                        {/* ================= DETAILS ================= */}

                        <div
                            className="product-details"
                            id="details"
                        >
                            <div className="detail-card glass-card">
                                <h3>
                                    {
                                        product.detailTitle
                                    }
                                </h3>

                                <p>
                                    {
                                        product.detailDesc
                                    }
                                </p>
                            </div>

                            <div className="detail-card glass-card">
                                <h3>
                                    What you get
                                </h3>

                                <p>
                                    {product.packageIncludes.join(
                                        " · "
                                    )}
                                </p>
                            </div>
                        </div>
                    </section>
                </div>
            </main>
        </div>
    );
}